      when "<" then l < r
      when ">=" then l >= r
      when "<=" then l <= r
      else false
      end
    rescue ArgumentError, TypeError
      false
    end
  end
end

def is_numeric(s)
  t = s.sub(/\A-/, '')
  !t.empty? && t =~ /\A\d+\z/
end

